INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Lying_Prone_Quadriceps', 'Lying Prone Quadriceps', 'legs', ARRAY[]::text[], 'bodyweight', 'stretching', 'expert', 'Lay face down on the floor with your partner kneeling beside you. Flex one knee and raise that leg off the ground, attempting to touch your glutes with your foot. Your partner should hold the knee and ankle. This will be your starting position. Attempt to extend your knee while your partner prevents any actual movement. After 10-20 seconds, relax your muscles as your partner gently pushes the foot towards your glutes, further stretching the quadriceps and hip flexors. After 10-20 seconds, switch'),
('Lying_Rear_Delt_Raise', 'Lying Rear Delt Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'While holding a dumbbell in each hand, lay with your chest down on a flat bench. Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position. Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also'),
('Lying_Supine_Dumbbell_Curl', 'Lying Supine Dumbbell Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Lie down on a flat bench face up while holding a dumbbell in each arm on top of your thighs. Bring the dumbbells to the sides with the arms extended and the palms of the hands facing your thighs (neutral grip). While keeping the arms close to your torso and elbows in, slowly lower your arms (as you keep them extended with a slight bend at the elbows) as far down towards the floor as you can go. Once you cannot go down any further, lock your upper arms in that position and that will be your start'),
('Lying_T-Bar_Row', 'Lying T-Bar Row', 'back', ARRAY['arms','back']::text[], 'machine', 'strength', 'intermediate', 'Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad. Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize. Lift the bar off the rack and extend your arms '),
('Lying_Triceps_Press', 'Lying Triceps Press', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'intermediate', 'Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor. Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position. As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper ar'),
('Machine_Bench_Press', 'Machine Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Sit down on the Chest Press Machine and select the weight. Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms. Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be a'),
('Machine_Bicep_Curl', 'Machine Bicep Curl', 'arms', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position. Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm. Pause at the top of the movement, and then slowly return the weight to the starting position. Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.'),
('Machine_Preacher_Curls', 'Machine Preacher Curls', 'arms', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Sit down on the Preacher Curl Machine and select the weight. Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position. Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. '),
('Machine_Shoulder_Military_Press', 'Machine Shoulder (Military) Press', 'shoulders', ARRAY['arms']::text[], 'machine', 'strength', 'beginner', 'Sit down on the Shoulder Press Machine and select the weight. Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position. Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second. Lower the handles slowly back to the starting position as you inhale. Repeat for the recommended amount of repetitions.'),
('Machine_Triceps_Extension', 'Machine Triceps Extension', 'arms', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position. Perform the movement by extending the elbow, pulling your lower arm away from your upper arm. Pause at the completion of the movement, and then slowly return the weight to the starting position. Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.'),
('Medicine_Ball_Chest_Pass', 'Medicine Ball Chest Pass', 'chest', ARRAY['shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'You will need a partner for this exercise. Lacking one, this movement can be performed against a wall. Begin facing your partner holding the medicine ball at your torso with both hands. Pull the ball to your chest, and reverse the motion by extending through the elbows. For sports applications, you can take a step as you throw. Your partner should catch the ball, and throw it back to you. Receive the throw with both hands at chest height.'),
('Medicine_Ball_Full_Twist', 'Medicine Ball Full Twist', 'core', ARRAY['shoulders']::text[], 'other', 'plyometrics', 'beginner', 'For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. This will be your starting position. Hold the ball in front of the trunk. Open the hips and turn the shoulders at the same time as your partner. For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise. Pass the ball to your partner, and both of you can now twist in the opposite direction to repeat the procedure.'),
('Medicine_Ball_Scoop_Throw', 'Medicine Ball Scoop Throw', 'shoulders', ARRAY['core','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Assume a semisquat stance with a medicine ball in your hands. Your arms should hang so the ball is near your feet. Begin by thrusting the hips forward as you extend through the legs, jumping up. As you do, swing your arms up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you.'),
('Middle_Back_Shrug', 'Middle Back Shrug', 'back', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position. As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms. As you inhale go back to the starting posi'),
('Middle_Back_Stretch', 'Middle Back Stretch', 'back', ARRAY['core','back','back']::text[], 'other', 'stretching', 'beginner', 'Stand so your feet are shoulder width apart and your hands are on your hips. Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side.'),
('Mixed_Grip_Chin', 'Mixed Grip Chin', 'back', ARRAY['arms','back']::text[], 'other', 'strength', 'expert', 'Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position. Now start to pull yourself up as you exhale. Tip: With the arm that has the palms facing up concentrate on using the back muscles in order to perform the movement. The elbow of that arm should remain close to the torso. With the other arm that has the palms facing forward, the elb'),
('Monster_Walk', 'Monster Walk', 'legs', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart. To begin, take short steps forward alternating your left and right foot. After several steps, do just the opposite and walk backward to where you started.'),
('Mountain_Climbers', 'Mountain Climbers', 'legs', ARRAY['chest','legs','shoulders']::text[], 'other', 'plyometrics', 'beginner', 'Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position. Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds.'),
('Moving_Claw_Series', 'Moving Claw Series', 'legs', ARRAY['legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends. Reload the quad as the leg moves back forward, attacking the ground on the next step. Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion.'),
('Muscle_Snatch', 'Muscle Snatch', 'legs', ARRAY['legs','back','legs','shoulders','arms']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position. Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possi'),
('Muscle_Up', 'Muscle Up', 'back', ARRAY['core','arms','arms','back','shoulders','back','arms']::text[], 'other', 'strength', 'intermediate', 'Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement. Maintaining control and stability, extend through the elbow to complete the mot'),
('Narrow_Stance_Hack_Squats', 'Narrow Stance Hack Squats', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'intermediate', 'Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided. Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times. Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by movin'),
('Narrow_Stance_Leg_Press', 'Narrow Stance Leg Press', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'intermediate', 'Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times. Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure tha'),
('Narrow_Stance_Squats', 'Narrow Stance Squats', 'legs', ARRAY['legs','legs','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a l'),
('Natural_Glute_Ham_Raise', 'Natural Glute Ham Raise', 'legs', ARRAY['legs','legs','back']::text[], 'bodyweight', 'strength', 'intermediate', 'Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture. This will be your starting position. Lower yourself under control until your knees are almost completely straight. Remaining in control, raise yourself back up to the starting position. If you are unable to complete a rep, use a band, a partner, or push off of a b'),
('Neck-SMR', 'Neck-SMR', 'other', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Using a muscle roller or a rolling pin, place the roller behind your head and against your neck. Make sure that you do not place the roller directly against the spine, but turned slightly so that the roller is pressed against the muscles to either side of the spine. This will be your starting position. Starting at the top of your neck, slowly roll down the muscles of your neck, pausing at points of tension for 10-30 seconds.'),
('Neck_Press', 'Neck Press', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'intermediate', 'Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your neck. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arm'),
('Oblique_Crunches', 'Oblique Crunches', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor. Make sure your feet are elevated and resting on a flat surface. Now lift the shoulder in which your hand is touching your head. Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elb'),
('Oblique_Crunches_-_On_The_Floor', 'Oblique Crunches - On The Floor', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit. Place your left hand behind your head. Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques. Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position. Remember to breathe in during the eccentric (lowering'),
('Olympic_Squat', 'Olympic Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with a barbell supported on top of the traps. The chest should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed. Descend by flexing the knees, refraining from moving the hips back as much as possible. This requires that the knees travel forward; ensure that they stay aligned with the feet. The goal is to keep the torso as upright as possible. Continue all the way down, keeping the weight on the front of the heel. At the moment the upper legs c'),
('On-Your-Back_Quad_Stretch', 'On-Your-Back Quad Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Lie on a flat bench or step, and hang one leg and arm over the side. Bend the knee and hold the top of the foot. As you do this, be careful not to arch your lower back. Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you''re holding up toward the ceiling. Switch sides.'),
('On_Your_Side_Quad_Stretch', 'On Your Side Quad Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso). Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides.'),
('One-Arm_Dumbbell_Row', 'One-Arm Dumbbell Row', 'back', ARRAY['arms','back','shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'Choose a flat bench and place a dumbbell on each side of it. Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support. Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position. Pull the resistance straight '),
('One-Arm_Flat_Bench_Dumbbell_Flye', 'One-Arm Flat Bench Dumbbell Flye', 'chest', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh. The palm of your hand with the dumbbell in it should be at a neutral grip. By using your thighs to help you get the dumbbell up, clean the dumbbell so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat bench for better support. This will be your starting position. Your '),
('One-Arm_High-Pulley_Cable_Side_Bends', 'One-Arm High-Pulley Cable Side Bends', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Connect a standard handle to a tower. Move cable to highest pulley position. Stand with side to cable. With one hand, reach up and grab handle with underhand grip. Pull down cable until elbow touches your side and the handle is by your shoulder. Position feet hip-width apart. Place free hand on hip to help gauge pivot point. Keep arm in static position. Contract oblique to bring the weight down in a side crunch. Once you reach maximum contraction, slowly release the weight to the starting positi'),
('One-Arm_Incline_Lateral_Raise', 'One-Arm Incline Lateral Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel. Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position. While keeping the dumbbell parallel to the floor at all times, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. '),
('One-Arm_Kettlebell_Clean', 'One-Arm Kettlebell Clean', 'legs', ARRAY['legs','back','shoulders','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. Return the weight to the starting position.'),
('One-Arm_Kettlebell_Clean_and_Jerk', 'One-Arm Kettlebell Clean and Jerk', 'shoulders', ARRAY[]::text[], 'kettlebell', 'strength', 'intermediate', 'Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move t'),
('One-Arm_Kettlebell_Floor_Press', 'One-Arm Kettlebell Floor Press', 'chest', ARRAY['arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in. Press the kettlebell straight up toward the ceiling, rotating your wrist. Lower the kettlebell back to the starting position and repeat.'),
('One-Arm_Kettlebell_Jerk', 'One-Arm Kettlebell Jerk', 'shoulders', ARRAY['legs','legs','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, '),
('One-Arm_Kettlebell_Military_Press_To_The_Side', 'One-Arm Kettlebell Military Press To The Side', 'shoulders', ARRAY['arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces inward. This will be your starting position. Look at the kettlebell and press it up and out until it is locked out overhead. Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and st'),
('One-Arm_Kettlebell_Para_Press', 'One-Arm Kettlebell Para Press', 'shoulders', ARRAY['arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position. Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead. Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefu'),
('One-Arm_Kettlebell_Push_Press', 'One-Arm Kettlebell Push Press', 'shoulders', ARRAY['legs','legs','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, '),
('One-Arm_Kettlebell_Row', 'One-Arm Kettlebell Row', 'back', ARRAY['arms','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat.'),
('One-Arm_Kettlebell_Snatch', 'One-Arm Kettlebell Snatch', 'shoulders', ARRAY['legs','legs','legs','back','back','arms']::text[], 'kettlebell', 'strength', 'expert', 'Place a kettlebell between your feet. Bend your knees and push your butt back to get in the proper starting position. Look straight ahead and swing the kettlebell back between your legs. Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward. As the kettlebell rises to your shoulder rotate your hand and punch straight up, using momentum to receive the weight locked out overhead.'),
('One-Arm_Kettlebell_Split_Jerk', 'One-Arm Kettlebell Split Jerk', 'shoulders', ARRAY['legs','legs','legs','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, '),
('One-Arm_Kettlebell_Split_Snatch', 'One-Arm Kettlebell Split Snatch', 'shoulders', ARRAY['legs','legs']::text[], 'kettlebell', 'strength', 'expert', 'Hold a kettlebell in one hand by the handle. Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead. After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion. Return to a standing position, holding the weight overhead, and bring the feet toge'),
('One-Arm_Kettlebell_Swings', 'One-Arm Kettlebell Swings', 'legs', ARRAY['legs','legs','back','shoulders']::text[], 'kettlebell', 'strength', 'intermediate', NULL),
('One-Arm_Long_Bar_Row', 'One-Arm Long Bar Row', 'back', ARRAY['arms','back']::text[], 'barbell', 'strength', 'beginner', 'Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end. Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position. Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position. Pull the weight to your side by retracting the shoulder and flexing the elbow. Do not jerk the weight or cheat during the moveme'),
('One-Arm_Medicine_Ball_Slam', 'One-Arm Medicine Ball Slam', 'core', ARRAY['back','shoulders']::text[], 'other', 'strength', 'beginner', 'Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as your back leg. This will be your starting position. Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, knees, and ankles to load up for the slam. At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground directly in front of you. Catch the ball on the bounce and continue for the desired n')
